#include "universr.hpp"
#include <chrono>
#include <cstring>
#include <fstream>
#include <string>
#include <vector>
namespace{
struct Wav{int sr=0;std::vector<float>d;};
bool read_wav(const char*p,Wav&w){std::ifstream f(p,std::ios::binary);if(!f)return false;std::vector<uint8_t>b((std::istreambuf_iterator<char>(f)),{});if(b.size()<12||memcmp(b.data(),"RIFF",4)||memcmp(b.data()+8,"WAVE",4))return false;int ch=1,bits=16,fmt=1;size_t off=0,sz=0,q=12;while(q+8<=b.size()){uint32_t n=*reinterpret_cast<const uint32_t*>(&b[q+4]);if(!memcmp(&b[q],"fmt ",4)&&q+24<=b.size()){fmt=*reinterpret_cast<const uint16_t*>(&b[q+8]);ch=*reinterpret_cast<const uint16_t*>(&b[q+10]);w.sr=*reinterpret_cast<const int32_t*>(&b[q+12]);bits=*reinterpret_cast<const uint16_t*>(&b[q+22]);}else if(!memcmp(&b[q],"data",4)){off=q+8;sz=n;}q+=8+n+(n&1);}if(!off||!ch||!w.sr)return false;size_t frames=sz/(bits/8*ch);w.d.resize(frames);for(size_t i=0;i<frames;i++){double a=0;for(int c=0;c<ch;c++){const uint8_t*z=&b[off+(i*ch+c)*(bits/8)];if(fmt==3&&bits==32){float v;memcpy(&v,z,4);a+=v;}else if(bits==16){int16_t v;memcpy(&v,z,2);a+=v/32768.0;}else if(bits==24){int32_t v=z[0]|(z[1]<<8)|(z[2]<<16);if(v&0x800000)v-=0x1000000;a+=v/8388608.0;}else if(bits==32){int32_t v;memcpy(&v,z,4);a+=v/2147483648.0;}else return false;}w.d[i]=(float)(a/ch);}return true;}
void write_wav(const char*p,const std::vector<float>&d,int sr){std::ofstream f(p,std::ios::binary);int32_t n=d.size(),br=sr*2,db=n*2,ch=36+db;int16_t one=1,two=2,s16=16;f.write("RIFF",4);f.write((char*)&ch,4);f.write("WAVE",4);f.write("fmt ",4);int32_t fmt=16;f.write((char*)&fmt,4);f.write((char*)&one,2);f.write((char*)&one,2);f.write((char*)&sr,4);f.write((char*)&br,4);f.write((char*)&two,2);f.write((char*)&s16,2);f.write("data",4);f.write((char*)&db,4);for(float v:d){int16_t s=(int16_t)((v>1?1:(v<-1?-1:v))*32767);f.write((char*)&s,2);}}
}
int main(int argc,char**argv){if(argc==2&&std::string(argv[1])=="selftest"){std::vector<float>x(245760);for(size_t i=0;i<x.size();++i)x[i]=0.1f*std::sin(2*3.14159265f*1000*i/48000);auto s=univ::stft(x);auto y=univ::istft(s,245760);double a=0,b=0;for(size_t i=0;i<y.size();++i){a+=x[i]*x[i];b+=y[i]*y[i];}printf("stft/istft rms %.5f/%.5f\n",std::sqrt(a/x.size()),std::sqrt(b/y.size()));return 0;}if(argc<4){fprintf(stderr,"usage: %s <models> <input.wav> <output.wav> [--sr 8|16]\n",argv[0]);return 1;}std::string models=argv[1],in=argv[2],out=argv[3];int sr=8;for(int i=4;i<argc;i++)if(!strcmp(argv[i],"--sr")&&i+1<argc)sr=atoi(argv[++i]);Wav w;if(!read_wav(in.c_str(),w)){fprintf(stderr,"read wav failed\n");return 1;}univ::UniverSR m;if(!m.load(models,sr)){fprintf(stderr,"model load failed\n");return 1;}auto t0=std::chrono::steady_clock::now();auto y=m.enhance(w.d,w.sr);auto t1=std::chrono::steady_clock::now();if(y.empty()){fprintf(stderr,"infer failed\n");return 1;}write_wav(out.c_str(),y,48000);double dt=std::chrono::duration<double>(t1-t0).count();printf("UniverSR: %d -> 48000, %.2fs, infer %.2fs RTF %.3f\n",w.sr,(double)w.d.size()/w.sr,dt,dt/(w.d.size()/(double)w.sr));return 0;}
